<script setup lang="ts">import{ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';const input=ref(''),supportRef=ref(''),loading=ref(false),error=ref('');async function submit(){loading.value=true;error.value='';try{supportRef.value=(await api.recoverOrder(input.value)).supportRef}catch{error.value='提交未确认；已保留输入，可稍后按原请求重试或通用申诉。'}finally{loading.value=false}}</script>
<template><view class="page"><AppHeader left="← 返回" right="帮助" @left="uni.navigateBack()"/><view class="content"><text class="kicker">订单恢复 / UX-P023</text><view class="heading" role="heading" aria-level="1">恢复原订单</view><text class="desc">恢复引用只用于定位请求，不证明身份或订单归属。</text><view class="field"><text>恢复信息</text><input v-model="input" placeholder="请输入已登记的最小信息"/></view><StatusNotice title="隐私一致响应">未认证、无权、不存在、他人订单和证据不足使用同一通用结果。</StatusNotice><StatusNotice v-if="error" tone="risk" title="恢复请求结果未确认">{{error}}</StatusNotice><view v-if="supportRef" class="card">SupportRef：{{supportRef}}</view></view><view class="action"><button class="primary" :disabled="loading||!input" @click="submit">按原请求提交/重试</button><button class="secondary" @click="uni.navigateTo({url:'/pages/support/case'})">下一复核 / 通用申诉</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.field{margin-top:28rpx;background:#fff;border:1rpx solid var(--line);padding:24rpx;border-radius:22rpx}.field text{display:block;color:var(--muted);font-size:22rpx}</style>
